"""Tables and pass rules for v0.5.   python v05/report.py  -> results/v05/tables.md, results/v05/summary.json"""
import json, os
import numpy as np
D = ["car", "nursery", "balance", "monks1", "monks2", "monks3", "lenses", "tictactoe"]; ARMS = ["program", "program+net", "net", "tree", "forest", "index"]; INF = float("inf")
def load(d, t): p = f"results/v05/{d}_t{t}.json"; return json.load(open(p)) if os.path.exists(p) else None
def med(xs): return float(np.median([INF if x is None else x for x in xs]))
def show(x): return "never" if x == INF else f"{x:.0f}"
P = ["# v0.5 result tables\n", "Generated by `v05/report.py`. Five seeds. \"Audits to 99%\" is the median over seeds of the first budget at which 99% of ALL cases in the table are right.\n"]; S = {"rules": {}, "datasets": {}}
def block(t, title, names):
    P.extend([f"## {title}\n", "| Dataset | Cases | Tests available | program | program+net | net | tree | forest | index | program, chosen audits | net, chosen audits |", "|---|---|---|---|---|---|---|---|---|---|---|"]); out = {}
    for d in names:
        r = load(d, t)
        if r is None: P.append(f"| {d} | – | – | not run | | | | | | | |"); continue
        m = {k: med(v["audits_to_99"]) for k, v in r["summary"].items()}; out[d] = (r, m)
        P.append(f"| {d} | {r['cases']} | {r['conditions']} | " + " | ".join(show(m[f"passive/{a}"]) for a in ARMS) + f" | {show(m['chosen/program'])} | {show(m['chosen/net'])} |")
    return out
R2 = block(2, "Primary: rules of at most 2 tests. Audits to 99%, passive audits unless stated", D)
P.append("\n**Share of all cases right at each budget, passive audits (mean of 5 seeds)**\n")
for d, (r, m) in R2.items():
    P.append(f"\n{d} (budgets {r['budgets']}; most common decision {100 * r['majority_share']:.0f}%):\n"); P.extend(["| Learner | " + " | ".join(str(b) for b in r["budgets"]) + " |", "|---|" + "---|" * len(r["budgets"])])
    for a in ARMS: P.append(f"| {a} | " + " | ".join(f"{100 * x:.1f}" for x in r["summary"][f"passive/{a}"]["right_all_by_budget"]) + " |")
P.extend(["\n**Cautious mode, averaged over the budgets below the full table (passive audits): wrong / abstained, % of all cases**\n", "| Dataset | program | net | forest | program lists that reproduce the evidence, at the last budget (of 7) |", "|---|---|---|---|---|"]); cw = {}
for d, (r, m) in R2.items():
    nb = [i for i, b in enumerate(r["budgets"]) if b < r["cases"]] or [0]; row = {}
    for a in ("program", "net", "forest"):
        s = r["summary"][f"passive/{a}"]; row[a] = (float(np.mean([s["cautious_wrong_by_budget"][i] for i in nb])), float(np.mean([s["cautious_abstained_by_budget"][i] for i in nb])))
    cw[d] = row; rep = np.mean([x.get("lists_that_reproduce_the_evidence", 0) for x in r["curves"]["passive/program"][-1]])
    P.append(f"| {d} | " + " | ".join(f"{100 * row[a][0]:.2f} / {100 * row[a][1]:.1f}" for a in ("program", "net", "forest")) + f" | {rep:.1f} |")
# ---- pass rules ----
def count(f): return [d for d, (r, m) in R2.items() if f(d, r, m)]
r1 = count(lambda d, r, m: m["passive/program"] < INF and m["passive/program"] <= m["passive/net"])
r2 = count(lambda d, r, m: cw[d]["program"][0] <= 0.5 * cw[d]["net"][0])
r3 = count(lambda d, r, m: m["passive/program"] < INF and m["passive/program"] <= m["passive/tree"])
r4 = count(lambda d, r, m: m["chosen/program"] < m["passive/program"])
r5a = count(lambda d, r, m: m["passive/program+net"] < INF and m["passive/program+net"] <= m["passive/program"]); r5b = count(lambda d, r, m: m["passive/program+net"] < m["passive/program"])
n = len(R2); rules = [("R1. Program needs no more audits than the network (5 of 8 needed)", r1, len(r1) >= 5), ("R2. Program's cautious wrong share at most half the network's (5 of 8)", r2, len(r2) >= 5),
                      ("R3. Program needs no more audits than a decision tree (4 of 8)", r3, len(r3) >= 4), ("R4. Chosen audits beat passive for the program learner (5 of 8)", r4, len(r4) >= 5),
                      ("R5. Network as proposer: no later on 5 of 8 and strictly earlier on 2", r5a, len(r5a) >= 5 and len(r5b) >= 2)]
P.extend([f"\n## Pass rules (frozen in `docs/v05_spec.md`; {n} of 8 datasets run)\n", "| Rule | Datasets where it holds | Result |", "|---|---|---|"])
for name, ds, ok in rules: P.append(f"| {name} | {len(ds)}: {', '.join(ds) or 'none'} | {'PASS' if ok else 'FAIL'} |"); S["rules"][name] = {"datasets": ds, "pass": ok}
P.append(f"\nR5 detail: program+net strictly earlier than program on {len(r5b)}: {', '.join(r5b) or 'none'}.")
P.append("\nNetwork against tree (not a pre-set rule): net reaches 99% with fewer audits than tree on " + ", ".join(count(lambda d, r, m: m["passive/net"] < m["passive/tree"])) + ".")
P.append("")
R3 = block(3, "Secondary (pre-set, labelled): rules of at most 3 tests, datasets with at most 2,000 cases", [d for d in D if d != "nursery"])
for d, (r, m) in R3.items(): P.append(f"\n{d}, 3 tests, program, share of all cases right by budget {r['budgets']}: " + ", ".join(f"{100 * x:.1f}" for x in r["summary"]["passive/program"]["right_all_by_budget"]) + f". Run time {r['seconds']:.0f} s (2 tests: {R2[d][0]['seconds']:.0f} s)." if d in R2 else "")
for d, (r, m) in R2.items(): S["datasets"][d] = {k: (None if v == INF else v) for k, v in m.items()}
open("results/v05/tables.md", "w").write("\n".join(P) + "\n"); json.dump(S, open("results/v05/summary.json", "w"), indent=1); print("\n".join(P[:14])); print("\n".join(x for x in P if x.startswith("| R") or x.startswith("R5") or x.startswith("\nNetwork")))
